CREATE TABLE modelo_reuniao (
 id text PRIMARY KEY DEFAULT gen_random_uuid()::text, igreja_id text NOT NULL, contexto_id text NOT NULL,
 finalidade text NOT NULL, configuracao jsonb NOT NULL, revisao integer NOT NULL DEFAULT 1,
 FOREIGN KEY(contexto_id,igreja_id) REFERENCES contexto_secretaria(id,igreja_id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX modelo_reuniao_contexto_id_finalidade_key ON modelo_reuniao(contexto_id,finalidade);
CREATE UNIQUE INDEX reuniao_segunda_convocacao_key ON reuniao ((dados->>'primeira_reuniao_id')) WHERE dados->>'primeira_reuniao_id' IS NOT NULL;
CREATE FUNCTION instalar_modelos_reuniao(ctx contexto_secretaria) RETURNS void LANGUAGE sql AS $$
 INSERT INTO modelo_reuniao(igreja_id,contexto_id,finalidade,configuracao)
 SELECT ctx.igreja_id,ctx.id,m.finalidade,m.config::jsonb FROM orgao_interno o JOIN (VALUES
