SELECT instalar_modelos_reuniao(c) FROM contexto_secretaria c;
CREATE FUNCTION novos_modelos_reuniao() RETURNS trigger LANGUAGE plpgsql AS $$
 BEGIN PERFORM instalar_modelos_reuniao(NEW); RETURN NEW; END; $$;
CREATE TRIGGER novos_modelos_reuniao AFTER INSERT ON contexto_secretaria FOR EACH ROW EXECUTE FUNCTION novos_modelos_reuniao();
